package com.ncrox.satanachia;

import android.app.*;
import android.os.*;
import android.os.Environment;
import android.provider.Settings;
import android.content.*;
import android.net.Uri;
import android.graphics.Color;
import android.graphics.Typeface;
import android.view.*;
import android.view.inputmethod.EditorInfo;
import android.widget.*;
import android.text.InputType;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public class MainActivity extends Activity {
  private TextView output; private EditText input; private Button accessButton;
  private ScrollView scroll; private FrameLayout root; private LinearLayout page, drawer, keyRow1, keyRow2;
  private View shade; private float downX,downY; private boolean drawerOpen=false;
  private final ExecutorService worker=Executors.newSingleThreadExecutor();
  private final ArrayList<Session> tabs=new ArrayList<>(); private int activeTab=0;
  private final ArrayList<String> history=new ArrayList<>(); private int historyPos=0; private boolean controlNext=false;
  private int bg,fg,accent,keyBg; private String prefix;
  private static class Session { File cwd; StringBuilder text=new StringBuilder(); Session(File d,String p){cwd=d;text.append(p);} }

  @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(Color.BLACK);getWindow().setNavigationBarColor(Color.BLACK);loadPrefs();tabs.add(new Session(chooseStartDir(),prefix));startKeepAliveService();buildUi();}
  private void loadPrefs(){android.content.SharedPreferences p=getSharedPreferences("ncrox",MODE_PRIVATE);prefix=p.getString("prefix","0───────~$[");String theme=p.getString("theme","green");if("amber".equals(theme)){bg=Color.rgb(12,10,6);fg=Color.rgb(255,190,70);accent=fg;keyBg=Color.rgb(40,31,16);}else if("light".equals(theme)){bg=Color.rgb(239,241,237);fg=Color.rgb(25,35,26);accent=Color.rgb(25,110,54);keyBg=Color.rgb(213,222,211);}else{bg=Color.BLACK;fg=Color.rgb(125,255,99);accent=fg;keyBg=Color.rgb(24,28,24);}}
  private void buildUi(){
    root=new FrameLayout(this);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setBackgroundColor(bg);page.setPadding(8,4,8,4);
    LinearLayout top=new LinearLayout(this);top.setOrientation(LinearLayout.HORIZONTAL);Button menu=new Button(this);menu.setText("☰");menu.setTextColor(fg);menu.setAllCaps(false);menu.setMinWidth(44);menu.setOnClickListener(v->showDrawer());top.addView(menu);TextView name=new TextView(this);name.setText("NCROX");name.setTextColor(accent);name.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);name.setTextSize(15);name.setGravity(Gravity.CENTER_VERTICAL);top.addView(name,new LinearLayout.LayoutParams(0,44,1));Button settings=new Button(this);settings.setText("⚙");settings.setTextColor(fg);settings.setAllCaps(false);settings.setMinWidth(44);settings.setOnClickListener(v->showSettings());top.addView(settings);page.addView(top);
    scroll=new ScrollView(this);output=new TextView(this);output.setTextColor(fg);output.setTextSize(14);output.setTypeface(Typeface.MONOSPACE);output.setTextIsSelectable(true);output.setPadding(2,2,2,4);scroll.addView(output);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
    accessButton=new Button(this);accessButton.setText("Conceder acesso aos arquivos");accessButton.setAllCaps(false);accessButton.setOnClickListener(v->requestFileAccess());page.addView(accessButton);
    keyRow1=new LinearLayout(this);keyRow1.setOrientation(LinearLayout.HORIZONTAL);addKey(keyRow1,"ESC",()->insert("\u001b"));addKey(keyRow1,"TAB",this::submit);addKey(keyRow1,"CTRL",()->controlNext=!controlNext);addKey(keyRow1,"ALT",()->insert("\u001b"));addKey(keyRow1,"↑",()->historyMove(-1));addKey(keyRow1,"HOME",()->moveCursor(false));addKey(keyRow1,"END",()->moveCursor(true));page.addView(keyRow1);
    keyRow2=new LinearLayout(this);keyRow2.setOrientation(LinearLayout.HORIZONTAL);addKey(keyRow2,"←",()->moveBy(-1));addKey(keyRow2,"↓",()->historyMove(1));addKey(keyRow2,"→",()->moveBy(1));addKey(keyRow2,"PGUP",()->scrollByPage(-1));addKey(keyRow2,"PGDN",()->scrollByPage(1));addKey(keyRow2,"LOCK",this::toggleWakeLock);page.addView(keyRow2);
    input=new EditText(this);input.setSingleLine(true);input.setTextColor(fg);input.setHintTextColor(Color.GRAY);input.setHint("");input.setTypeface(Typeface.MONOSPACE);input.setTextSize(14);input.setImeOptions(EditorInfo.IME_ACTION_NONE|EditorInfo.IME_FLAG_NO_EXTRACT_UI);input.setBackgroundTintList(android.content.res.ColorStateList.valueOf(accent));page.addView(input,new LinearLayout.LayoutParams(-1,-2));
    input.setOnKeyListener((v,k,e)->{if(k==KeyEvent.KEYCODE_TAB&&e.getAction()==KeyEvent.ACTION_DOWN){submit();return true;}if(k==KeyEvent.KEYCODE_ENTER&&e.getAction()==KeyEvent.ACTION_DOWN)return true;if(k==KeyEvent.KEYCODE_DPAD_UP&&e.getAction()==KeyEvent.ACTION_DOWN){historyMove(-1);return true;}if(k==KeyEvent.KEYCODE_DPAD_DOWN&&e.getAction()==KeyEvent.ACTION_DOWN){historyMove(1);return true;}if(controlNext&&e.getAction()==KeyEvent.ACTION_DOWN&&e.getUnicodeChar()!=0){char c=(char)e.getUnicodeChar();if(c>='@'&&c<='_'){insert(String.valueOf((char)(c-'@')));controlNext=false;return true;}}return false;});
    input.setOnEditorActionListener((v,a,e)->{if(a==EditorInfo.IME_ACTION_DONE){submit();return true;}return false;});
    root.addView(page,new FrameLayout.LayoutParams(-1,-1));buildDrawer();setContentView(root);refreshPermissions();renderSession();
  }
  private void buildDrawer(){
    shade=new View(this);shade.setBackgroundColor(0x99000000);shade.setVisibility(View.GONE);shade.setOnClickListener(v->hideDrawer());root.addView(shade,new FrameLayout.LayoutParams(-1,-1));
    drawer=new LinearLayout(this);drawer.setOrientation(LinearLayout.VERTICAL);drawer.setPadding(14,28,14,12);drawer.setBackgroundColor(bg);FrameLayout.LayoutParams dp=new FrameLayout.LayoutParams((int)(getResources().getDisplayMetrics().widthPixels*.82),-1,Gravity.LEFT);drawer.setTranslationX(-dp.width);root.addView(drawer,dp);
    TextView title=new TextView(this);title.setText("NCROX  ·  ABAS");title.setTextColor(accent);title.setTextSize(18);title.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);title.setPadding(8,4,4,18);drawer.addView(title);
    Button newTab=new Button(this);newTab.setText("+ Nova aba");newTab.setAllCaps(false);newTab.setTextColor(fg);newTab.setOnClickListener(v->{hideDrawer();saveSession();tabs.add(new Session(chooseStartDir(),prefix));activeTab=tabs.size()-1;history.clear();historyPos=0;renderSession();});drawer.addView(newTab);
    for(int i=0;i<tabs.size();i++){final int idx=i;Button tab=new Button(this);tab.setAllCaps(false);tab.setTextColor(idx==activeTab?accent:fg);String label=(idx==activeTab?"● ":"○ ")+"Aba "+(idx+1)+"   "+shortPath(tabs.get(i).cwd);tab.setText(label);tab.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);tab.setOnClickListener(v->{hideDrawer();saveSession();activeTab=idx;history.clear();historyPos=0;renderSession();});drawer.addView(tab);}
    View spacer=new View(this);drawer.addView(spacer,new LinearLayout.LayoutParams(1,0,1));Button cfg=new Button(this);cfg.setText("⚙  Configurações");cfg.setAllCaps(false);cfg.setTextColor(fg);cfg.setOnClickListener(v->{hideDrawer();showSettings();});drawer.addView(cfg);
  }
  private String shortPath(File f){String s=f.getName();return s.isEmpty()?"/":s;}
  private void saveSession(){if(activeTab<tabs.size()){tabs.get(activeTab).cwd=cwd();tabs.get(activeTab).text=new StringBuilder(output.getText());}}
  private File cwd(){return tabs.get(activeTab).cwd;}
  private void renderSession(){Session s=tabs.get(activeTab);output.setText(s.text);if(s.text.length()==0||s.text.charAt(s.text.length()-1)!=' ')output.append("\n"+prefix+" ");scroll.post(()->scroll.fullScroll(ScrollView.FOCUS_DOWN));input.requestFocus();}
  private void showDrawer(){buildDrawer();shade.setVisibility(View.VISIBLE);drawer.animate().translationX(0).setDuration(180).start();drawerOpen=true;}
  private void hideDrawer(){if(!drawerOpen)return;drawer.animate().translationX(-drawer.getWidth()).setDuration(160).withEndAction(()->shade.setVisibility(View.GONE)).start();drawerOpen=false;}
  @Override public boolean dispatchTouchEvent(android.view.MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN){downX=e.getX();downY=e.getY();}else if(e.getAction()==MotionEvent.ACTION_UP){float dx=e.getX()-downX,dy=e.getY()-downY;if(Math.abs(dx)>90&&Math.abs(dx)>Math.abs(dy)*1.3){if(!drawerOpen&&downX<32&&dx>0){showDrawer();return true;}if(drawerOpen&&dx<0){hideDrawer();return true;}}}return super.dispatchTouchEvent(e);}
  private void showSettings(){loadPrefs();LinearLayout box=new LinearLayout(this);box.setPadding(22,8,22,0);box.setOrientation(LinearLayout.VERTICAL);EditText pfx=new EditText(this);pfx.setSingleLine(true);pfx.setHint("Prefixo do prompt");pfx.setText(prefix);box.addView(pfx);Spinner themes=new Spinner(this);ArrayAdapter<String> ad=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,new String[]{"Verde escuro","Âmbar","Claro"});ad.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);themes.setAdapter(ad);String current=getSharedPreferences("ncrox",MODE_PRIVATE).getString("theme","green");themes.setSelection(current.equals("amber")?1:current.equals("light")?2:0);box.addView(themes);new AlertDialog.Builder(this).setTitle("Configurações").setView(box).setNegativeButton("Cancelar",(d,w)->{}).setPositiveButton("Salvar",(d,w)->{String val=pfx.getText().toString().trim();if(val.isEmpty())val="0───────~$[";String theme=themes.getSelectedItemPosition()==1?"amber":themes.getSelectedItemPosition()==2?"light":"green";getSharedPreferences("ncrox",MODE_PRIVATE).edit().putString("prefix",val).putString("theme",theme).apply();prefix=val;loadPrefs();for(Session s:tabs){if(s.text.length()==0||s.text.toString().endsWith("0───────~$[ ")){int ix=s.text.lastIndexOf("0───────~$[ ");if(ix>=0)s.text.replace(ix,s.text.length(),prefix+" ");}}buildUi();}).show();}
  private void addKey(LinearLayout row,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setTextSize(10);b.setTextColor(fg);b.setAllCaps(false);b.setPadding(0,0,0,0);b.setMinHeight(0);b.setMinimumHeight(0);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(keyBg));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,38,1);lp.setMargins(1,0,1,2);row.addView(b,lp);b.setOnClickListener(v->action.run());}
  private void startKeepAliveService(){Intent i=new Intent(this,TerminalService.class);i.setAction(TerminalService.ACTION_START);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}
  private File chooseStartDir(){File shared=Environment.getExternalStorageDirectory();if(hasFileAccess()&&shared!=null&&shared.isDirectory())return shared;return getFilesDir();}
  private boolean hasFileAccess(){return Build.VERSION.SDK_INT<30||Environment.isExternalStorageManager();}
  private void refreshPermissions(){if(accessButton!=null)accessButton.setVisibility(hasFileAccess()?View.GONE:View.VISIBLE);if(hasFileAccess()&&activeTab<tabs.size())tabs.get(activeTab).cwd=Environment.getExternalStorageDirectory();}
  private void requestFileAccess(){if(Build.VERSION.SDK_INT>=30){try{startActivity(new Intent(Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION,Uri.parse("package:"+getPackageName())));}catch(Exception e){startActivity(new Intent(Settings.ACTION_MANAGE_ALL_FILES_ACCESS_PERMISSION));}}}
  private void toggleWakeLock(){boolean old=getSharedPreferences("ncrox",MODE_PRIVATE).getBoolean("wake_lock",false);setWakeLock(!old);}
  private void setWakeLock(boolean on){getSharedPreferences("ncrox",MODE_PRIVATE).edit().putBoolean("wake_lock",on).apply();Intent i=new Intent(this,TerminalService.class);i.setAction(on?TerminalService.ACTION_LOCK:TerminalService.ACTION_UNLOCK);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}
  private void showPrompt(){output.append(prefix+" ");scroll.post(()->scroll.fullScroll(ScrollView.FOCUS_DOWN));input.requestFocus();}
  private void submit(){String cmd=input.getText().toString().trim();input.setText("");if(cmd.isEmpty())return;output.append(cmd+"\n");history.add(cmd);historyPos=history.size();saveSession();worker.execute(()->{String result=run(cmd);runOnUiThread(()->{if(!result.isEmpty())output.append(result+"\n");saveSession();showPrompt();saveSession();});});}
  private void insert(String s){int at=Math.max(0,input.getSelectionStart());input.getText().insert(at,s);input.setSelection(at+s.length());input.requestFocus();}
  private void moveCursor(boolean end){input.setSelection(end?input.length():0);input.requestFocus();}private void moveBy(int d){int at=Math.max(0,input.getSelectionStart());input.setSelection(Math.max(0,Math.min(input.length(),at+d)));}private void scrollByPage(int n){scroll.smoothScrollBy(0,n*Math.max(100,scroll.getHeight()*3/4));input.requestFocus();}private void historyMove(int d){if(history.isEmpty())return;historyPos=Math.max(0,Math.min(history.size(),historyPos+d));input.setText(historyPos==history.size()?"":history.get(historyPos));input.setSelection(input.length());}
  private String run(String command){try{String[] a=command.trim().split("\\s+");String c=a[0];if(c.equals("exit")||c.equals("quit"))return "";if(c.equals("help")||c.equals("ajuda"))return "Atalhos: pwd, cd, make, tree, pick, net faces, acquire lock, release lock, tabs, settings.";if(c.equals("clear")||c.equals("cls")){runOnUiThread(()->output.setText(""));return "";}if(c.equals("pwd"))return cwd().getAbsolutePath();if(c.equals("cd")){File f=a.length>1?new File(cwd(),a[1]):chooseStartDir();if(f.isDirectory()){tabs.get(activeTab).cwd=f.getCanonicalFile();return "";}return "cd: diretório inválido";}if(c.equals("make")||c.equals("mkdir")){if(a.length<2)return "Uso: make [-p] pasta";boolean parents=false;String name=a[a.length-1];for(String x:a)if(x.equals("-p")||x.equals("--parents"))parents=true;File f=new File(cwd(),name);boolean ok=parents?f.mkdirs():f.mkdir();return ok?"":"make: não foi possível criar diretório";}if(c.equals("tree")||c.equals("ls")){File f=a.length>1?new File(cwd(),a[1]):cwd();if(!f.canRead())return "tree: sem acesso";StringBuilder b=new StringBuilder(f.getName().isEmpty()?f.getAbsolutePath():f.getName());tree(f,"",b,0);return b.toString();}if(c.equals("pick")){if(a.length<2)return "Uso: pick URL|usuario/repo";String url=a[1];if(!url.contains("://")&&!url.startsWith("git@"))url="https://github.com/"+url.replaceAll("\\.git$","")+".git";return shell("git clone "+quote(url));}if(c.equals("net")){if(a.length>1&&(a[1].equals("faces")||(a.length>2&&a[1].equals("-show"))))return shell("ip addr");return "Uso: net faces | net -show -all";}if(c.equals("acquire")&&a.length>1&&a[1].equals("lock")){setWakeLock(true);return "Wake lock ligado";}if(c.equals("release")&&a.length>1&&a[1].equals("lock")){setWakeLock(false);return "Wake lock desligado";}if(c.equals("tabs")){return "Abas abertas: "+tabs.size()+" (toque ☰ para alternar/criar)";}if(c.equals("settings")){runOnUiThread(this::showSettings);return "";}return shell(command);}catch(Exception e){return "Erro: "+e.getMessage();}}
  private String quote(String s){return "'"+s.replace("'","'\\''")+"'";}private String shell(String cmd){try{Process p=new ProcessBuilder("/system/bin/sh","-c",cmd).directory(cwd()).redirectErrorStream(true).start();ByteArrayOutputStream b=new ByteArrayOutputStream();InputStream in=p.getInputStream();byte[] x=new byte[2048];int n,total=0;while((n=in.read(x))>0&&total<65536){b.write(x,0,n);total+=n;}int code=p.waitFor();String out=b.toString("UTF-8").trim();if(out.isEmpty())out=code==0?"":"Código de saída: "+code;if(total>=65536)out+="\n[saída truncada]";return out;}catch(Exception e){return "Erro: "+e.getMessage();}}
  private void tree(File dir,String prefix,StringBuilder b,int depth){if(depth>=7)return;File[] fs=dir.listFiles();if(fs==null)return;Arrays.sort(fs,(x,y)->Boolean.compare(!x.isDirectory(),!y.isDirectory()));for(int i=0;i<fs.length&&i<150;i++){File f=fs[i];boolean last=i==fs.length-1;b.append("\n").append(prefix).append(last?"╰── ":"──╮─ ").append(f.getName()).append(f.isDirectory()?"/":"");if(f.isDirectory())tree(f,prefix+(last?"    ":"│   "),b,depth+1);}}
  @Override protected void onResume(){super.onResume();refreshPermissions();}
  @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
